struct ring { void *items[CAP]; size_t head, tail, count; pthread_mutex_t m; };
int ring_push(struct ring *r, void *item) {      /* policy: REJECT | DROP_OLDEST | BLOCK */
    pthread_mutex_lock(&r->m);
    if (r->count == CAP) {
        if (POLICY != DROP_OLDEST) { pthread_mutex_unlock(&r->m); return RING_FULL; }
        r->head = (r->head + 1) % CAP; r->count--;   /* make room by losing the oldest */
    }
    r->items[r->tail] = item; r->tail = (r->tail + 1) % CAP; r->count++;
    pthread_mutex_unlock(&r->m);                 /* BLOCK: pthread_cond_wait here instead */
    return RING_OK;
}
